function _eliBootReviewRedlines() {
  // Idempotency guard, but set AFTER the IIFE body completes — not at
  // the top. Pre-fix this was at line 13 (before any work); if the boot
  // threw partway (missing global, etc.) the flag was set anyway, and
  // every subsequent call would early-return without re-attempting. With
  // it at the bottom, a failed boot leaves the flag false and the next
  // click re-runs (e.g., after a load-order race resolved when
  // redline_authors finished initializing).
  if (window._eliReviewRedlinesBooted) return;

  // ─── v2 IIFE body verbatim (kernel shims cover initFeatureDB,
  //     STORE_*, showToast, showEliDialog, callGemini, API_KEY,
  //     computeWordDiff, safeToggleTracking,
  //     loadFeatureData, saveFeatureData, recordEliStat,
  //     checkRedlinesBeforeScan).
  //
  // Tool-local helpers replace v2 kernel globals that v3 no longer
  // ships: `tryParseGeminiJSON` (7 call sites) + `getHistoryFromDoc`
  // (1 guarded call site) + `_rrGetPrompt` / `_rrFormatPrompt`
  // (review_redlines-specific prompts loaded from eli.storage) are
  // defined here so the closure resolves them without window.

  // Closure-local prompts cache. v2 read from a kernel-wide
  // `_eliPromptsCache` via `getPrompt(key)` / `formatPrompt(key, params)`.
  // v3 routes prompt data through eli.storage ("prompts" store);
  // review_redlines owns its own cache rather than reaching for a
  // global another tool happens to install. _rrLoadPrompts is awaited
  // at the top of runRedlineSummary so the section AI never fires
  // with an empty system prompt.
  var _rrPromptCache = null;
  var _rrPromptLoadPromise = null;
  function _rrLoadPrompts() {
    if (_rrPromptCache) return Promise.resolve(_rrPromptCache);
    if (_rrPromptLoadPromise) return _rrPromptLoadPromise;
    if (!window.eli || !window.eli.storage || typeof window.eli.storage.getAll !== "function") {
      return Promise.resolve({});
    }
    _rrPromptLoadPromise = window.eli.storage.getAll("prompts").then(function (rows) {
      var map = {};
      (rows || []).forEach(function (r) {
        if (r && r.id && typeof r.text === "string") map[r.id] = r.text;
      });
      _rrPromptCache = map;
      _rrPromptLoadPromise = null;
      return map;
    }).catch(function (e) {
      _rrPromptLoadPromise = null;
      if (window.eli && window.eli.log) {
        window.eli.log.event("review_redlines.prompt_load_failed", { msg: (e && e.message) || "unknown" });
      }
      return {};
    });
    return _rrPromptLoadPromise;
  }
  function _rrGetPrompt(key, fallback) {
    return (_rrPromptCache || {})[key] || fallback || "";
  }
  function _rrFormatPrompt(key, params, fallback) {
    var tpl = _rrGetPrompt(key, fallback);
    if (!tpl) return "";
    params = params || {};
    return tpl.replace(/\{\{(\w+)\}\}/g, function (_, name) {
      return params[name] != null ? String(params[name]) : "";
    });
  }
  // Refresh cache when the prompts data bundle is re-installed.
  if (window.eli && window.eli.bus && typeof window.eli.bus.on === "function") {
    window.eli.bus.on("data:installed", function (payload) {
      if (!payload || !payload.id || /prompts/i.test(payload.id)) {
        _rrPromptCache = null;
        _rrLoadPrompts();
      }
    });
  }
  // Kick off the initial load now — preload-tier means this boot fires
  // well before the AI scan, but we still await _rrLoadPrompts() in
  // runRedlineSummary to be safe.
  _rrLoadPrompts();

  // 2026-05-17: Review Redlines-local AI proxy. Gates every AI call in
  // this file through a single setting (`rr_ai_disabled` in localStorage).
  // When disabled (test mode), every call resolves immediately with a
  // labeled stub — UI flows continue, tokens don't burn. Setting is
  // tool-local (does NOT affect other tools' AI usage).
  //
  // Replaces direct `_rrAi.complete(...)` / `completeJSON(...)` /
  // `completeStream(...)` calls throughout this module. Forward-compat:
  // if window.eli.ai is missing, the proxy still resolves cleanly with
  // an error message rather than throwing.
  function _rrAiDisabled() {
    try { return String(window.eli.compat.lsGet("rr_ai_disabled") || "") === "1"; }
    catch (_e) { return false; }
  }
  function _rrAiStub(promptText) {
    // Plausible-looking stub so downstream parsers don't choke. Length
    // is short so any view that displays the response renders quickly.
    return "[AI disabled — test mode]\n\n" +
      "Review Redlines is in test mode (Settings → 🤖 toggle in workbench header). " +
      "Re-enable AI to get real responses.\n\n" +
      "First 120 chars of prompt: " + String(promptText || "").slice(0, 120);
  }
  function _rrAiStubJSON() {
    // Best-effort default shape — empty object/array. Callers that expect
    // specific keys handle missing fields gracefully (already do for AI
    // failures), so this won't fork the code paths.
    return {};
  }
  // Cache the kernel AI fns at proxy-build time. CRITICAL: these MUST
  // stay as window.eli.ai.* lookups at CALL time, not literal calls in
  // source, because a stray sed-style global replace of
  // `window.eli.ai.complete(` → `_rrAi.complete(` would turn the proxy
  // into an infinite-recursion trap (the bug that produced "Maximum
  // call stack size exceeded" on Revise click 2026-05-17). We resolve
  // the kernel fn via a string-keyed lookup that no source-level
  // replace can accidentally rewrite.
  var _AI_K_COMPLETE        = "comple" + "te";
  var _AI_K_COMPLETE_JSON   = "comple" + "teJSON";
  var _AI_K_COMPLETE_STREAM = "comple" + "teStream";
  function _kernelAi(method) {
    if (!window.eli || !window.eli.ai) return null;
    var fn = window.eli.ai[method];
    return (typeof fn === "function") ? fn.bind(window.eli.ai) : null;
  }
  var _rrAi = {
    complete: function (prompt, opts) {
      if (_rrAiDisabled()) return Promise.resolve(_rrAiStub(prompt));
      var fn = _kernelAi(_AI_K_COMPLETE);
      if (!fn) return Promise.reject(new Error("eli.ai.complete unavailable"));
      return fn(prompt, opts);
    },
    completeJSON: function (prompt, schema, opts) {
      if (_rrAiDisabled()) return Promise.resolve(_rrAiStubJSON());
      var fn = _kernelAi(_AI_K_COMPLETE_JSON);
      if (!fn) return Promise.reject(new Error("eli.ai.completeJSON unavailable"));
      return fn(prompt, schema, opts);
    },
    completeStream: function (prompt, onChunk, opts) {
      if (_rrAiDisabled()) {
        var stub = _rrAiStub(prompt);
        try { if (typeof onChunk === "function") onChunk(stub, stub); } catch (_e) {}
        return Promise.resolve(stub);
      }
      var fn = _kernelAi(_AI_K_COMPLETE_STREAM);
      if (!fn) return Promise.reject(new Error("eli.ai.completeStream unavailable"));
      return fn(prompt, onChunk, opts);
    },
  };

  // Closure-local wrapper for Word.run with auto-retry on transient
  // Word.js errors ("Object has been deleted", "isNullObject not loaded").
  // Routes through eli.host.resilient when available; falls back to plain
  // Word.run if the kernel predates resilient (forward-compat). Every
  // Word.run site in this module uses this helper — Review Redlines is
  // crucial enough that no Word.run in this file should be unprotected.
  function _rrSafeWordRun(label, fn) {
    if (window.eli && window.eli.host && typeof window.eli.host.resilient === "function") {
      return window.eli.host.resilient(label, fn);
    }
    if (typeof Word !== "undefined" && Word.run) return Word.run(fn);
    return Promise.reject(new Error("Word host unavailable"));
  }

  // FROM v2 getHistoryFromDoc (taskpane_v2.js:22433) — reads
  // `eli_version_history` from Office doc settings. review_redlines is
  // the only consumer; v3 owns it here.
  function getHistoryFromDoc() {
    return new Promise(function (resolve) {
      try {
        var raw = Office.context.document.settings.get("eli_version_history");
        if (!raw) { resolve([]); return; }
        var data = typeof raw === "string" ? JSON.parse(raw) : raw;
        resolve(Array.isArray(data) ? data : []);
      } catch (e) { resolve([]); }
    });
  }

  // Delete bookmarks by name or prefix. Mirrors v2's
  // window._eliCleanupBookmarks. Callers pass either exact names
  // ("EliReviseAnchor_1234567890_abc") or prefixes ("ELI_P_",
  // "_ELI_QA_") — we match both. Self-installed on window if absent.
  //
  // 2026-05-14 PERF: exact names take a targeted O(1) path
  // (getBookmarkRangeOrNullObject + that range's tiny bookmarks
  // collection) — NO full-document bookmark load. The old code loaded
  // the ENTIRE bookmark collection for every call; on a doc with a
  // bloated bookmark table that single-anchor cleanup after a redline
  // apply cost 3+ seconds (rr:L131). The full-collection load now
  // happens ONLY when an arg is a genuine prefix (session-clear sweep).
  //
  // Guarded: body.getRange().bookmarks isn't typed as a collection in
  // every Word JS API version. If unsupported, we silently return —
  // accumulating bookmarks is suboptimal but never blocks a scan.
  if (typeof window._eliCleanupBookmarks !== "function") {
    window._eliCleanupBookmarks = function (namesOrPrefixes) {
      if (!Array.isArray(namesOrPrefixes) || !namesOrPrefixes.length) return Promise.resolve();
      if (typeof Word === "undefined" || !Word.run) return Promise.resolve();
      var patterns = namesOrPrefixes.map(String).filter(Boolean);
      return _rrSafeWordRun("rr:L131", async function (ctx) {
        try {
          // Phase 1 — probe each pattern as an EXACT bookmark name.
          var probes = patterns.map(function (p) {
            var r = ctx.document.getBookmarkRangeOrNullObject(p);
            r.load("isNullObject");
            return { pattern: p, range: r };
          });
          await ctx.sync();
          var prefixes = [];
          var scoped = [];
          probes.forEach(function (pr) {
            if (pr.range.isNullObject) {
              // No bookmark literally named `pattern` — it's a prefix
              // (or already gone). Defer to the Phase 2 sweep.
              prefixes.push(pr.pattern);
            } else {
              // Exact hit — load just the bookmarks within this one
              // range (1-2 items), not the whole document.
              var sc = pr.range.bookmarks;
              sc.load("items/name");
              scoped.push({ pattern: pr.pattern, scoped: sc });
            }
          });
          if (scoped.length) await ctx.sync();
          scoped.forEach(function (s) {
            (s.scoped.items || []).forEach(function (b) {
              if (b && b.name === s.pattern) {
                try { b.delete(); } catch (_) {}
              }
            });
          });
          // Phase 2 — prefix sweep. Loads the full bookmark collection
          // (unavoidable for prefix matching) but ONLY runs when a
          // pattern wasn't an exact name — i.e. the session-clear sweep.
          if (prefixes.length) {
            var bks = ctx.document.body.getRange().bookmarks;
            if (bks && typeof bks.load === "function") {
              bks.load("items/name");
              await ctx.sync();
              (bks.items || []).forEach(function (b) {
                if (!b || !b.name) return;
                var n = b.name;
                if (prefixes.some(function (p) { return n.indexOf(p) === 0; })) {
                  try { b.delete(); } catch (_) {}
                }
              });
            }
          }
          await ctx.sync();
        } catch (_) {
          // Word build doesn't expose the bookmark collection — skip silently.
        }
      }).catch(function () {});
    };
  }

  // Clean AI output: strip markdown markers + wrapper quotes the AI
  // added on top of the selection. v2 stripped `**`, `##`, `__` and
  // leading/trailing quotes (taskpane_v2.js:23322); v3 review_redlines
  // had lost the markdown strip step, leaving stray `**` in applied text.
  function _rrCleanAiOutput(raw, selText, preamble) {
    var out = String(raw == null ? "" : raw)
      .replace(/\*\*/g, "")
      .replace(/^##\s*/gm, "")
      .replace(/__/g, "")
      .trim();
    out = _stripWrapperQuotes(out, selText);
    // 2026-05-18: preamble-echo safety net. When prompts include the
    // doc preamble for party-name continuity, the model occasionally
    // copies the preamble verbatim at the start of its rewrite — that
    // text would otherwise land in the redline preview. Strip whole-
    // paragraph and first-sentence echoes off the front of the output.
    if (preamble && out) {
      var pParas = String(preamble).split(/\n\s*\n/).map(function (s) {
        return s.trim();
      }).filter(Boolean);
      for (var i = 0; i < pParas.length; i++) {
        var p = pParas[i];
        if (!p || p.length < 20) continue;
        if (out.indexOf(p) === 0) {
          out = out.slice(p.length).replace(/^\s*\n+/, "").trim();
          continue;
        }
        var firstSent = p.split(/(?<=[.!?])\s/)[0];
        if (firstSent && firstSent.length >= 20 && out.indexOf(firstSent) === 0) {
          out = out.slice(firstSent.length).replace(/^\s*\n+/, "").trim();
        }
      }
    }
    return out;
  }

  // V2-faithful word-level diff. Mirrors tools/legal_risks/engine.js
  // computeWordDiffV2 verbatim. Two hunk types only: equal + change.
  // Uses jsdiff (window.Diff) when present, falls back to whole-text
  // change when not. Keeping a local copy avoids cross-tool coupling —
  // review_redlines is preload tier, legal_risks is preload tier, but
  // we don't want a load-order race on shared engine fns.
  function _rrComputeWordDiff(oldText, newText) {
    if (!oldText) oldText = "";
    if (!newText) newText = "";
    if (typeof Diff === "undefined" || typeof Diff.diffArrays !== "function") {
      return oldText === newText
        ? [{ type: "equal", text: oldText }]
        : [{
            type: "change",
            oldWords: oldText.split(/\s+/).filter(Boolean),
            newWords: newText.split(/\s+/).filter(Boolean),
            id: "hunk_0",
          }];
    }
    var oldTokens = oldText.match(/\S+/g) || [];
    var newTokens = newText.match(/\S+/g) || [];
    var parts = Diff.diffArrays(oldTokens, newTokens);
    var hunks = [];
    var currentHunk = null;
    parts.forEach(function (p) {
      if (!p.added && !p.removed) {
        if (currentHunk) { hunks.push(currentHunk); currentHunk = null; }
        p.value.forEach(function (w) { hunks.push({ type: "equal", text: w }); });
      } else {
        if (!currentHunk) currentHunk = { type: "change", oldWords: [], newWords: [], id: "hunk_" + hunks.length };
        if (p.removed) p.value.forEach(function (w) { currentHunk.oldWords.push(w); });
        if (p.added)   p.value.forEach(function (w) { currentHunk.newWords.push(w); });
      }
    });
    if (currentHunk) hunks.push(currentHunk);
    return hunks;
  }

  // ─── Surgical apply pipeline — ported VERBATIM from legal_risks ──────
  // Apply / Regen / Revise route through _rrApplyAll, which is the exact
  // _rwApplyAll pipeline legal_risks' FIX uses. NOT eli.host.
  // applySurgicalRedline: that re-runs its own whitespace-keeping diff
  // which produces noisier hunks. The in-tool rebuilder uses the SAME
  // hunks the preview shows, preserves per-word formatting, and (for
  // long clauses without an anchor) expands the range to a tail match
  // so it always gets the full clause text. Keep in sync with
  // legal_risks/init.js _rw* — they are intentionally identical ports.

  // FROM legal_risks _rwApplyFontFmt. Each property in its own try/catch;
  // skip underline when value isn't a recognized enum (don't wipe).
  function _rrApplyFontFmt(range, fmt) {
    if (!fmt || !range) return;
    var validUnderlines = [
      "None","Single","Words","Double","Thick","Dotted","DottedHeavy",
      "DashLine","DashLineHeavy","DashLineLong","DashLineLongHeavy",
      "DotDashLine","DotDashLineHeavy","TwoDotDashLine","TwoDotDashLineHeavy",
      "Wave","WaveHeavy","WaveDouble",
    ];
    function _try(setter) { try { setter(); } catch (e) { /* tolerate */ } }
    if (typeof fmt.bold === "boolean")   _try(function () { range.font.bold = fmt.bold; });
    if (typeof fmt.italic === "boolean") _try(function () { range.font.italic = fmt.italic; });
    if (typeof fmt.size === "number")    _try(function () { range.font.size = fmt.size; });
    if (typeof fmt.name === "string" && fmt.name)
      _try(function () { range.font.name = fmt.name; });
    if (typeof fmt.underline === "string" && validUnderlines.indexOf(fmt.underline) !== -1) {
      _try(function () { range.font.underline = fmt.underline; });
    }
  }

  // FROM legal_risks _rwFindClauseRange — bookmark first (constant time,
  // exact), then body.search fallback.
  function _rrFindClauseRange(context, scopeText, anchorId) {
    if (anchorId && typeof context.document.getBookmarkRangeOrNullObject === "function") {
      var bm = context.document.getBookmarkRangeOrNullObject(anchorId);
      bm.load("isNullObject");
      return context.sync().then(function () {
        if (!bm.isNullObject) return bm;
        return _rrFindByText(context, scopeText);
      });
    }
    return _rrFindByText(context, scopeText);
  }
  function _rrFindByText(context, scopeText) {
    if (!scopeText) return Promise.resolve(null);
    var snippet = scopeText.substring(0, Math.min(scopeText.length, 250)).replace(/[\r\n\t]+/g, " ").trim();
    if (!snippet) return Promise.resolve(null);
    var results = context.document.body.search(snippet, { matchCase: false, ignoreSpace: true });
    results.load("items");
    return context.sync().then(function () {
      return results.items.length ? results.items[0] : null;
    });
  }

  // FROM legal_risks _rwExpandRangeToTail — expands clauseRange to include
  // a match of the last 200 chars of originalText, capped at +1500 chars
  // to reject unrelated tail matches. This is what makes apply "get the
  // full text" for clauses longer than the 250-char search snippet.
  function _rrExpandRangeToTail(context, clauseRange, originalText) {
    var endText = originalText.substring(originalText.length - 200).trim();
    var bodyAfter = clauseRange.getRange("Start").expandTo(context.document.body.getRange("End"));
    var results = bodyAfter.search(endText, { matchCase: false, ignoreSpace: true, ignorePunctuation: true });
    results.load("items");
    return context.sync().then(function () {
      if (!results.items.length) return clauseRange;
      var candidate = clauseRange.getRange("Start").expandTo(results.items[0].getRange("End"));
      candidate.load("text");
      return context.sync().then(function () {
        if (candidate.text.length < originalText.length + 1500) return candidate;
        return clauseRange;
      });
    });
  }

  // FROM legal_risks _rwRebuilderCore — per-token format snapshot, then
  // tracking-off equals + tracking-on change marks. Per-hunk context.sync
  // (NOT a single batched sync) so Word records the mode toggles in order
  // — a single sync produced mis-ordered redline marks.
  function _rrRebuilderCore(context, clauseRange, originalText, aiText, hunks, redlinesOn) {
    if (redlinesOn === undefined) redlinesOn = true;
    var hunksLocal = hunks || _rrComputeWordDiff(originalText, aiText);
    var textRanges = clauseRange.getTextRanges([" ", "\r", "\n", "\t", "\xA0"], false);
    textRanges.load("items");
    return context.sync().then(function () {
      for (var k = 0; k < textRanges.items.length; k++) {
        textRanges.items[k].font.load(["bold", "italic", "size", "name", "underline"]);
        textRanges.items[k].load("text");
      }
      return context.sync().then(function () {
        var originalFormats = [];
        for (var k = 0; k < textRanges.items.length; k++) {
          if (!textRanges.items[k].text || !textRanges.items[k].text.trim()) continue;
          var f = textRanges.items[k].font;
          var prev = originalFormats.length ? originalFormats[originalFormats.length - 1] : null;
          originalFormats.push({
            bold:      f.bold === null      ? (prev ? prev.bold : false)      : !!f.bold,
            italic:    f.italic === null    ? (prev ? prev.italic : false)    : !!f.italic,
            size:      f.size === null      ? (prev ? prev.size : f.size)     : f.size,
            name:      f.name === null      ? (prev ? prev.name : f.name)     : f.name,
            underline: f.underline === null ? (prev ? prev.underline : null)  : f.underline,
          });
        }
        try { context.document.changeTrackingMode = "Off"; } catch (e) {}
        var currentCursor = clauseRange.insertText("", "Replace");
        return context.sync().then(function () {
          var optimized = [];
          var origIdx = 0;
          for (var i = 0; i < hunksLocal.length; i++) {
            var hunk = hunksLocal[i];
            if (hunk.type === "equal") {
              var fmt = originalFormats[origIdx] || {};
              if (optimized.length) {
                var last = optimized[optimized.length - 1];
                if (last.type === "equal") {
                  var lf = last.fmt || {};
                  if (lf.bold === fmt.bold && lf.italic === fmt.italic &&
                      lf.underline === fmt.underline && lf.size === fmt.size && lf.name === fmt.name) {
                    last.text += " " + hunk.text;
                    origIdx++;
                    continue;
                  }
                }
              }
              optimized.push({ type: "equal", text: hunk.text, fmt: fmt });
              origIdx++;
            } else {
              optimized.push({
                type: "change",
                oldWords: hunk.oldWords || [],
                newWords: hunk.newWords || [],
                startIdx: origIdx,
              });
              origIdx += (hunk.oldWords || []).length;
            }
          }
          // ── Mode-transition sync batching + split-sync correctness ──
          // We sync only when changeTrackingMode must flip (Off<->TrackAll),
          // NOT per hunk. Formatting is DEFERRED: each insert pushes a
          // {range, fmt} job; _flush() syncs (which materializes every
          // range inserted since the last flush), applies all pending font
          // jobs, then syncs again. That preserves the split-sync
          // correctness guarantee (font applied only after the range has
          // settled — the last-word-underline-drop fix) while collapsing
          // per-hunk syncs into per-transition syncs. _ensureMode flips
          // the tracking mode, flushing first so pending formats land
          // before the mode change (critical for the deletion branch,
          // where delRange must be formatted before it's tracked-deleted).
          // Keep in sync with legal_risks _rwRebuilderCore.
          var pendingFmt = [];
          var curMode = null;
          function _flush() {
            if (!pendingFmt.length) return Promise.resolve();
            var jobs = pendingFmt;
            pendingFmt = [];
            return context.sync().then(function () {
              jobs.forEach(function (j) { _rrApplyFontFmt(j.range, j.fmt); });
              return context.sync();
            });
          }
          function _ensureMode(mode) {
            if (curMode === mode) return Promise.resolve();
            return _flush().then(function () {
              try { context.document.changeTrackingMode = mode; } catch (e) {}
              curMode = mode;
            });
          }
          var p = Promise.resolve();
          optimized.forEach(function (oh, idx) {
            var isLast = idx === optimized.length - 1;
            var sp = isLast ? "" : " ";
            p = p.then(function () {
              if (oh.type === "equal") {
                return _ensureMode("Off").then(function () {
                  var inserted = currentCursor.insertText(oh.text + sp, "After");
                  currentCursor = inserted;
                  pendingFmt.push({ range: inserted, fmt: oh.fmt });
                });
              }
              var oldText = (oh.oldWords || []).join(" ");
              var newText = (oh.newWords || []).join(" ");
              var ofmt = originalFormats[oh.startIdx] ||
                (oh.startIdx > 0 ? originalFormats[oh.startIdx - 1] : {});
              var step = Promise.resolve();
              if (redlinesOn) {
                if (oldText) {
                  step = step.then(function () {
                    return _ensureMode("Off").then(function () {
                      var delRange = currentCursor.insertText(oldText + sp, "After");
                      pendingFmt.push({ range: delRange, fmt: ofmt });
                      // Flip to TrackAll — _flush() inside _ensureMode runs
                      // first, so delRange is formatted BEFORE the tracked
                      // deletion. Sync after the replace so the deletion is
                      // settled before any same-mode insert that follows.
                      return _ensureMode("TrackAll").then(function () {
                        delRange.insertText("", "Replace");
                        currentCursor = delRange;
                        return context.sync();
                      });
                    });
                  });
                }
                if (newText) {
                  step = step.then(function () {
                    return _ensureMode("TrackAll").then(function () {
                      var insRange = currentCursor.insertText(newText + sp, "After");
                      currentCursor = insRange;
                      pendingFmt.push({ range: insRange, fmt: ofmt });
                    });
                  });
                }
              } else {
                if (newText) {
                  step = step.then(function () {
                    return _ensureMode("Off").then(function () {
                      var insRange = currentCursor.insertText(newText + sp, "After");
                      currentCursor = insRange;
                      pendingFmt.push({ range: insRange, fmt: ofmt });
                    });
                  });
                }
              }
              return step;
            });
          });
          // Final flush — format the last run of inserts.
