  // Strip ONLY wrapper quotes the AI added on top of the selection.
  // The naive `replace(/^["“”']|["“”']$/g, "")` ate real content when the
  // user's selection itself started or ended with a quote (e.g. selecting
  // `"deliverable"` would return `new deliverable` because Inter's
  // surrounding curly quotes got stripped). Now: only strip a leading/
  // trailing quote when the original selection didn't already carry one
  // at that edge.
  function _stripWrapperQuotes(aiRaw, selText) {
    var out = String(aiRaw == null ? "" : aiRaw).trim();
    var src = String(selText == null ? "" : selText).trim();
    var isQ = function (ch) { return ch === '"' || ch === "“" || ch === "”" || ch === "'"; };
