  // Playbook lookup — reads STORE_PLAYBOOKS via eli.storage and resolves a
  // playbook record by agreement type with three matching tiers:
  // exact id, case-insensitive id, then a hand-maintained alias table for
  // common doc-type name variations (NDA / Non-Disclosure / Mutual NDA,
  // SOW / Statement of Work, etc.), then a normalized-substring fallback.
  // Tool-local closure (referenced inside the v2 IIFE body via closure scope,
  // no window global). Replaces the v2 window._getPlaybookForType +
  // window._loadTrackPortPlaybooks pair which lived on the kernel.
  function _getPlaybookForType(agreementType) {
    return window.eli.storage.getAll("playbooks").catch(function () { return []; }).then(function (rows) {
      var map = {};
      (rows || []).forEach(function (entry) { if (entry && entry.id) map[entry.id] = entry; });
      var key = (agreementType || "").trim();
