      var norm = function (s) {
        return s.toLowerCase().replace(/\b(agreement|mutual|confidentiality)\b/g, "").replace(/[^a-z]/g, "");
      };
      var nKey = norm(key);
      if (nKey.length >= 3) {
        for (var k = 0; k < keys.length; k++) {
          var nStored = norm(keys[k]);
          if (nStored.length >= 3 && (nKey.indexOf(nStored) !== -1 || nStored.indexOf(nKey) !== -1)) return map[keys[k]];
        }
      }
      return null;
    });
  }

