        (stack ? '<details style="margin-top:8px;"><summary style="font-size:10px;cursor:pointer;color:#991b1b;text-transform:uppercase;letter-spacing:0.1em;font-weight:700;">Stack</summary><pre style="font-size:10.5px;color:#581c1c;background:#fff5f5;padding:6px;margin-top:4px;overflow-x:auto;">' + String(stack).replace(/[<>&]/g, "") + '</pre></details>' : '');
