  // FROM v2 _tpBuildSectionsList (taskpane_v2.js:9566). Lived OUTSIDE the
  // 24645–32199 IIFE range the v3 port copied over, so it wasn't included
  // automatically. Builds the flat "article → section" list the sidebar +
  // workbench navigation use. Calls getOrderedPortArticleKeys, which is
  // defined later inside this same IIFE as a closure helper.
  function _tpBuildSectionsList(session) {
    if (!session || !session.groupedAi || typeof session.groupedAi !== "object") return [];
    var out = [];
    var articleKeys = (typeof getOrderedPortArticleKeys === "function")
      ? getOrderedPortArticleKeys(session.groupedAi)
      : Object.keys(session.groupedAi);
    articleKeys.forEach(function (articleKey) {
      var articleGroup = session.groupedAi[articleKey];
      if (!articleGroup || !articleGroup.sections) return;
      var articleLabel = articleGroup.article || articleKey;
      // 2026-05-18 v53: collect this article's sections into a local
      // array so they can be sorted by paragraph order before being
      // appended to `out`. Object.keys preserves insertion order, but
      // sections are inserted based on AI grouping which doesn't
      // guarantee paragraph order — leading to "8.4" listed before
      // "8.1" in the section map. Sorting by lowest row index per
      // section (= lowest sourceParagraphIndex in rawChanges, which IS
      // the doc paragraph order) restores paragraph order in the map.
      var thisArticleSections = [];
      Object.keys(articleGroup.sections).forEach(function (sectionKey) {
        var sec = articleGroup.sections[sectionKey];
        if (!sec) return;
        var rowIndices = [];
        (sec.clauses || []).forEach(function (clause) {
          var idx = Math.max(0, Number((clause && clause.revisionIndex) || 1) - 1);
          if (rowIndices.indexOf(idx) === -1) rowIndices.push(idx);
