        var sectionNumber = "";
        var rawRows = (session && Array.isArray(session.rawChanges)) ? session.rawChanges : [];
        // Tally every row's docSectionNumber and pick the most frequent;
        // ties break toward the more specific (more dot-segments) number.
        // readStructuralMap's getSection() walks backward to the nearest
        // header, so the first section of an article often resolves to
        // the ARTICLE header — taking [0] showed "8" for "8.1".
        var _numCounts = {};
        for (var ri = 0; ri < rowIndices.length; ri++) {
          var r = rawRows[rowIndices[ri]];
          var dsn = (r && r.docSectionNumber) ? String(r.docSectionNumber).trim() : "";
          if (dsn) _numCounts[dsn] = (_numCounts[dsn] || 0) + 1;
        }
        var _numKeys = Object.keys(_numCounts);
        if (_numKeys.length) {
          _numKeys.sort(function (a, b) {
            if (_numCounts[a] !== _numCounts[b]) return _numCounts[b] - _numCounts[a];
            return b.split(".").length - a.split(".").length;
          });
          sectionNumber = _numKeys[0];
        }
        // The structural walk-back can ONLY ever see the Article header
        // when a section's "X.Y" header isn't detected as structural —
        // then every row resolves to the bare article integer ("5").
        // The section LABEL ("5.1 Definitions", "Section 5.1") usually
        // carries the real dotted number. Prefer it whenever the
        // structural number is missing or article-level (no dot).
        var _labelMatch = String(sec.section || sectionKey || "").match(/\b(\d+(?:\.\d+)+)\b/);
        if (_labelMatch && (!sectionNumber || sectionNumber.indexOf(".") === -1)) {
          sectionNumber = _labelMatch[1];
        }
        if (window.eli && window.eli.log && typeof window.eli.log.event === "function") {
          window.eli.log.event("review_redlines.section_number", {
            articleKey: articleKey, sectionKey: sectionKey,
            label: String(sec.section || ""), tally: _numCounts,
            labelNum: _labelMatch ? _labelMatch[1] : "", picked: sectionNumber,
          });
        }
        // 2026-05-18 v53: compute firstParaIdx — the smallest
        // sourceParagraphIndex among this section's rows. Used to
        // sort sections within an article into doc paragraph order.
        // Falls back to lowest revisionIndex (= row order in
        // rawChanges) if sourceParagraphIndex isn't populated on the
        // row (legacy data / structural-map fallback).
        var firstParaIdx = Number.MAX_SAFE_INTEGER;
        for (var fri = 0; fri < rowIndices.length; fri++) {
          var fr = rawRows[rowIndices[fri]];
          var fp = (fr && typeof fr.sourceParagraphIndex === "number")
            ? fr.sourceParagraphIndex
            : rowIndices[fri];
          if (fp < firstParaIdx) firstParaIdx = fp;
        }
        thisArticleSections.push({
          articleKey: articleKey,
          sectionKey: sectionKey,
          articleLabel: articleLabel,
          sectionLabel: sec.section || sectionKey,
          sectionNumber: sectionNumber,
          cardKey: encodeURIComponent(articleKey) + "::" + encodeURIComponent(sectionKey),
          rowIndices: rowIndices,
          _firstParaIdx: firstParaIdx,
        });
      });
      // Sort sections within this article by lowest paragraph index.
      // Sections with no resolvable paragraph index (firstParaIdx ===
      // MAX_SAFE_INTEGER) sink to the bottom, preserving relative
      // order via the stable sort fallback.
      thisArticleSections.sort(function (a, b) {
        return (a._firstParaIdx || 0) - (b._firstParaIdx || 0);
      });
      thisArticleSections.forEach(function (s) { out.push(s); });
    });
