      if (!getRes.ok) return { ok: false, reason: "github_get_error", status: getRes.status };
      var existing = await getRes.json();
      var b64 = (existing.content || "").replace(/\s/g, "");
      var blob;
      try { blob = JSON.parse(atob(b64)); } catch (parseErr) { blob = null; }
      var envelope = null;
      if (blob && window._eliIsEncryptedBlob && window._eliIsEncryptedBlob(blob)) {
        envelope = await window._eliDecryptFromRepo(cipher, blob);
      } else if (blob && blob.sections) {
        envelope = blob;
      }
      if (!envelope) return { ok: false, reason: "decrypt_failed" };
      var res = await window._tcMergeRemoteEnvelope(envelope);
      _tcLastPullAt = Date.now();
      // Repaint the focus-shell team card if anything actually landed.
      // Silent merge — no toast (per user request). The new content
      // appears automatically next time the user navigates to a section
      // that has team commentary.
      if (res && ((res.added || 0) + (res.updated || 0)) > 0 &&
          typeof window._tcRefreshFocusShellTeam === "function") {
        try { window._tcRefreshFocusShellTeam(); } catch (_) {}
      }
      return { ok: true, added: (res && res.added) || 0, updated: (res && res.updated) || 0 };
    } catch (err) {
      return { ok: false, reason: "exception", msg: err && err.message };
    }
  };

