      };
    });
    redrawTags();
    var renderList = function () {
      return window._tcLoadForSection(sectionId).then(function (rows) {
        var listEl = document.getElementById("tcDlgList");
        if (!listEl) return;
        if (!rows.length) {
          listEl.innerHTML =
            '<div style="text-align:center; color:#94a3b8; font-size:11px; padding:32px 0;">' +
              'No team comments yet for this section. Be the first.' +
            '</div>';
          return;
        }
        listEl.innerHTML = rows.map(function (c) {
          var stateBadge = "";
          if (c.syncState === "local") stateBadge = '<span style="font-size:9px; color:#b45309; font-weight:700;">📤 unpublished</span>';
          else if (c.syncState === "publish_failed") stateBadge = '<span style="font-size:9px; color:#b91c1c; font-weight:700;">❌ publish failed</span>';
          else if (c.syncState === "published") stateBadge = '<span style="font-size:9px; color:#15803d; font-weight:700;">✓ published</span>';
          var dateStr = "";
          try {
            var d = new Date(c.createdAt);
            if (!isNaN(d.getTime())) {
              dateStr = String(d.getMonth() + 1).padStart(2, "0") + "/" +
                String(d.getDate()).padStart(2, "0") + "/" + String(d.getFullYear()).slice(-2);
            }
          } catch (_) { }
          var tagsHtml = (Array.isArray(c.tags) && c.tags.length)
            ? '<div style="margin-top:4px;">' + c.tags.map(function (t) {
                return '<span style="display:inline-block; font-size:9px; font-weight:600; color:#0f766e; ' +
                  'background:#ccfbf1; border:1px solid #99f6e4; padding:1px 6px; margin-right:4px; text-transform:lowercase;">#' +
                  _tcEsc(t) + '</span>';
              }).join("") + '</div>'
            : "";
          var canArchive = userEmail && c.authorEmail === userEmail;
          return '<div style="background:#fff; border:1px solid #e2e8f0; padding:10px 12px; margin-bottom:8px; ' +
            'border-left:3px solid ' + (c.authorEmail === userEmail ? "#0f766e" : "#94a3b8") + ';">' +
            '<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px; margin-bottom:4px;">' +
              '<div style="font-size:11px;">' +
                '<span style="font-weight:700; color:#0f172a;">' + _tcEsc(c.authorName || "(unknown)") + '</span>' +
                (c.authorGroup ? ' <span style="color:#64748b;">· ' + _tcEsc(c.authorGroup) + '</span>' : '') +
                (dateStr ? ' <span style="color:#94a3b8;">· ' + dateStr + '</span>' : '') +
              '</div>' +
              '<div style="display:flex; gap:6px; align-items:center;">' +
                stateBadge +
                (canArchive
                  ? ' <button data-tc-archive="' + _tcEsc(c.id) + '" title="Archive this comment" ' +
                    'style="padding:1px 6px; font-size:9px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b; border-radius:0;">archive</button>'
                  : '') +
              '</div>' +
            '</div>' +
            '<div style="font-size:12px; color:#0f172a; line-height:1.5; white-space:pre-wrap;">' + _tcEsc(c.text) + '</div>' +
            tagsHtml +
          '</div>';
        }).join("");
        listEl.querySelectorAll('[data-tc-archive]').forEach(function (btn) {
          btn.onclick = function () {
            var cid = btn.getAttribute("data-tc-archive");
            window.eli.ui.confirm({
              title: "Archive comment",
              message: "Archive this comment? It will disappear for everyone after the next push.",
            }).then(function (ok) {
              if (!ok) return;
              window._tcArchive(cid).then(function () {
                renderList();
                if (typeof window._tcRefreshFocusShellTeam === "function") {
                  try { window._tcRefreshFocusShellTeam(); } catch (_) { }
                }
                window._tcPushAllUnsynced().catch(function () { });
              });
            });
          };
        });
      });
    };
    renderList();
    document.getElementById("tcDlgSave").onclick = function () {
      var textEl = document.getElementById("tcDlgText");
      var statusEl = document.getElementById("tcDlgStatus");
      var raw = (textEl && textEl.value || "").trim();
      if (!raw) {
        if (statusEl) statusEl.innerHTML = '<span style="color:#b91c1c;">⚠️ Empty comment</span>';
        return;
      }
      if (!userEmail) {
        if (statusEl) statusEl.innerHTML = '<span style="color:#b91c1c;">⚠️ Set your email in Settings → Profile first</span>';
        return;
      }
      var saveBtn = document.getElementById("tcDlgSave");
      saveBtn.disabled = true;
      saveBtn.textContent = "⏳ Saving…";
      if (statusEl) statusEl.innerHTML = '<span style="color:#64748b;">Saving locally…</span>';
      var tagList = Object.keys(selectedTags).filter(function (k) { return selectedTags[k]; });
      window._tcCompose(sectionMeta, raw, tagList).then(function () {
        if (statusEl) statusEl.innerHTML = '<span style="color:#15803d;">✓ Saved locally. Publishing…</span>';
        textEl.value = "";
        Object.keys(selectedTags).forEach(function (k) { selectedTags[k] = false; });
        redrawTags();
        if (typeof window._tcRefreshFocusShellTeam === "function") {
          try { window._tcRefreshFocusShellTeam(); } catch (_) { }
        }
        return renderList();
      }).then(function () {
        return window._tcPushAllUnsynced();
      }).then(function (res) {
        if (statusEl) {
          if (res && res.ok) statusEl.innerHTML = '<span style="color:#15803d;">✓ Saved + published</span>';
          else if (res && res.reason === "no_pat") statusEl.innerHTML = '<span style="color:#b45309;">✓ Saved locally — no PAT, not published</span>';
          else if (res && res.reason === "no_cipher") statusEl.innerHTML = '<span style="color:#b45309;">✓ Saved locally — no library cipher, not published</span>';
          else if (res && res.reason === "no_repo") statusEl.innerHTML = '<span style="color:#b45309;">✓ Saved locally — no GitHub repo, not published</span>';
          else statusEl.innerHTML = '<span style="color:#b91c1c;">✓ Saved locally — publish failed (' + (res && (res.reason || res.status) || "?") + ')</span>';
        }
        if (typeof window._tcRefreshFocusShellTeam === "function") {
          try { window._tcRefreshFocusShellTeam(); } catch (_) { }
        }
        return renderList();
      }).catch(function (err) {
        if (statusEl) statusEl.innerHTML = '<span style="color:#b91c1c;">⚠️ ' + _tcEsc(String(err && err.message || err)) + '</span>';
      }).then(function () {
        saveBtn.disabled = false;
        saveBtn.textContent = "💾 Save";
      });
    };
  };

  window._eliTeamCommentaryBooted = true;
}

