    : '<div style="display:flex; flex-direction:column; gap:6px;">' +
      guidanceArr.map(function (g) {
        var rec = String(g.recommendation || "").toLowerCase();
        var recColor = rec === "accept" ? "#166534" : rec === "reject" ? "#991b1b" : "#92400e";
        var recBg = rec === "accept" ? "#dcfce7" : rec === "reject" ? "#fee2e2" : "#fef3c7";
        var recLabel = rec === "accept" ? "✓ Accept" : rec === "reject" ? "✕ Reject" : "✎ Revise";
        return '<div style="padding:10px 12px; background:#fff; border:1px solid #e2e8f0; border-left:3px solid ' + recColor + ';">' +
          '<div style="display:flex; align-items:center; gap:8px; margin-bottom:4px; flex-wrap:wrap;">' +
          '<span style="font-size:10px; font-weight:800; padding:2px 7px; background:' + recBg + '; color:' + recColor + '; text-transform:uppercase;">' + esc(recLabel) + '</span>' +
          (g.changeId != null ? '<span style="font-size:10px; color:#94a3b8; font-weight:700;">#' + esc(g.changeId) + '</span>' : '') +
          (g.author ? '<span style="font-size:11.5px; color:#475569; font-weight:600;">' + esc(g.author) + '</span>' : '') +
          '</div>' +
          (g.reason
            ? '<div style="font-size:12px; line-height:1.5; color:#0f172a;">' + esc(g.reason) + '</div>'
            : '') +
          '</div>';
      }).join("") + '</div>';
  // Build the modal
  var existing = document.getElementById("tpRiskScanModalOverlay");
  if (existing) existing.remove();
  var overlay = document.createElement("div");
  overlay.id = "tpRiskScanModalOverlay";
  overlay.style.cssText =
    "position:fixed; inset:0; z-index:99999; background:rgba(15,23,42,0.6); display:flex; align-items:center; justify-content:center; padding:20px; font-family:Inter,'Segoe UI',system-ui,sans-serif;";
  var box = document.createElement("div");
  box.style.cssText =
    "background:#fff; width:min(820px, 96vw); max-height:88vh; border:1px solid #cbd5e1; box-shadow:0 24px 60px rgba(15,23,42,0.5); display:flex; flex-direction:column; overflow:hidden;";
  box.innerHTML =
    '<div style="padding:16px 22px; background:linear-gradient(135deg,#991b1b,#b91c1c); color:#fff; display:flex; justify-content:space-between; align-items:flex-start;">' +
    '<div><div style="font-size:11px; font-weight:800; opacity:0.78; text-transform:uppercase; letter-spacing:1.4px;">⚖️  Risk Intelligence</div>' +
    '<div style="font-size:17px; font-weight:800; margin-top:3px;">' + esc(sectionTitleForModal) + '</div>' +
    '<div style="font-size:11px; opacity:0.78; margin-top:3px;">Scanning the section as if all redlines were accepted</div></div>' +
    '<button id="tpRiskScanCloseBtn" style="background:rgba(255,255,255,0.18); border:1px solid rgba(255,255,255,0.4); color:#fff; padding:6px 12px; font-size:11px; font-weight:700; cursor:pointer; border-radius:0;">✕ Close</button>' +
    '</div>' +
    '<div style="flex:1; overflow-y:auto; padding:16px 22px; background:#f8fafc;">' +
    '<div style="font-size:10px; font-weight:800; color:#991b1b; text-transform:uppercase; letter-spacing:0.7px; margin-bottom:8px;">Legal Risks (' + risksArr.length + ')</div>' +
    risksHtmlOut +
    '<div style="font-size:10px; font-weight:800; color:#0f172a; text-transform:uppercase; letter-spacing:0.7px; margin-top:18px; margin-bottom:8px;">Practical Guidance — Accept / Reject / Revise (' + guidanceArr.length + ')</div>' +
    guidanceHtmlOut +
    '</div>' +
    '<div style="padding:12px 22px; background:#f1f5f9; border-top:1px solid #cbd5e1; display:flex; gap:8px; justify-content:flex-end;">' +
    '<button id="tpRiskScanRescanBtn" style="padding:8px 14px; font-size:11px; font-weight:700; background:#fff; border:1px solid #dc2626; color:#dc2626; cursor:pointer;">↻ Re-scan</button>' +
    '<button id="tpRiskScanDoneBtn" style="padding:8px 14px; font-size:11px; font-weight:700; background:#1e40af; color:#fff; border:none; cursor:pointer;">Done</button>' +
    '</div>';
  overlay.appendChild(box);
  window._eliMountOverlay(overlay);
  // Close = remove modal AND reset the inline Scan button back to "Scan".
  var closeFn = function () {
    overlay.remove();
    var rb = document.getElementById("tpFocusRisksBtn");
    if (rb) {
      rb.disabled = false;
      rb.textContent = "Scan";
    }
  };
  document.getElementById("tpRiskScanCloseBtn").onclick = closeFn;
  document.getElementById("tpRiskScanDoneBtn").onclick = closeFn;
  overlay.onclick = function (e) { if (e.target === overlay) closeFn(); };
  // Re-scan inside modal — close + re-trigger
  document.getElementById("tpRiskScanRescanBtn").onclick = function () {
    closeFn();
    var rb = document.getElementById("tpFocusRisksBtn");
    if (rb && typeof rb.onclick === "function") rb.onclick();
  };
}

// ─── Helper #3: inline Legal Risks card in selection panel ───────────────
// Called from _tpRefreshSelectionPanel. Returns the HTML string for the
// inline Legal Risks card; caller concats it into the surrounding flex row
// next to Team Guidance. Uses _tpEsc from core for HTML escaping.

functions.legalRisksRenderSelectionCard:
function legalRisksRenderSelectionCard(legalRisks) {
  legalRisks = Array.isArray(legalRisks) ? legalRisks : [];
  var esc = (typeof _tpEsc === "function")
    ? _tpEsc
    : function (s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); };
  // ─── Legal Risks (inline card — header row matches Team Guidance height).
  // Margin is handled by the parent flex row that pairs this with Team Guidance.
  var riskCount = legalRisks.length;
  var risksHtml =
    '<div style="flex:1;min-width:0;background:#fff;border-left:4px solid #dc2626;">' +
    '<div style="display:flex;align-items:center;gap:7px;padding:8px 12px;">' +
    '<span style="font-size:9px;font-weight:900;color:#0f172a;text-transform:uppercase;letter-spacing:0.12em;flex:1;min-width:0;">Legal Risks' +
    (riskCount ? ' <span style="background:#dc2626;color:#fff;font-size:8px;font-weight:800;padding:1px 5px;margin-left:4px;">' + riskCount + '</span>' : '') +
    '</span>' +
    '<button id="tpFocusRisksBtn" style="padding:2px 8px;font-size:9px;font-weight:800;letter-spacing:0.05em;text-transform:uppercase;background:#fee2e2;border:1px solid #fecaca;color:#dc2626;cursor:pointer;border-radius:0;">' +
    (riskCount ? 'Re-scan' : 'Scan') +
    '</button>' +
    '</div>' +
    (legalRisks.length
      ? '<div style="padding:0 12px 10px 12px;">' +
      legalRisks.map(function (r, _i) {
        var title = r.title || r.issue || r.check || "Risk";
        var detail = r.detail || r.description || r.text || "";
        var sep = _i < legalRisks.length - 1 ? 'border-bottom:1px dashed #fecaca;' : '';
        return '<div style="padding:6px 0;' + sep + '">' +
          '<div style="font-size:12px;font-weight:700;color:#0f172a;line-height:1.35;">' + esc(title) + '</div>' +
          (detail ? '<div style="font-size:11.5px;line-height:1.45;color:#475569;margin-top:2px;">' + esc(detail) + '</div>' : '') +
          '</div>';
      }).join('') + '</div>'
      : '') +
    '</div>';
  return risksHtml;
}

// 2026-05-16: legalRisksRestoreActivity + legalRisksBuildPrompt removed.
// Restore is now owned by legal_risks/init.js _restoreActivity (registered
// on activity_restore["legal-360"]) which uses the clean v3 renderResults
// (data-action wiring). Prompt-building moved to legal_risks/engine.js.
// renderBalancedResults.js + runDeal360Analysis.js deleted alongside —
// they were the only consumers, all orphaned post-legal_risks migration.
// Filter the most recent legal-360 activity entry to risks matching a given
// section label (used by the inline Legal Risks card in the selection panel).
// Was inline in _tpRefreshSelectionPanel; moved here so the entire pipeline
// (filter + render) lives in the bundle.

functions.legalRisksFilterForSection:
function legalRisksFilterForSection(activityFeed, sectionLabel) {
  if (!Array.isArray(activityFeed)) return [];
  var legalEntry = activityFeed.find(function (a) {
    return a && a.type === "legal-360" && Array.isArray(a.payload);
  });
  if (!legalEntry || !Array.isArray(legalEntry.payload)) return [];
  var sLow = String(sectionLabel || "").toLowerCase();
  if (!sLow) return [];
  return legalEntry.payload.filter(function (r) {
    if (!r) return false;
    var ref = String(r.section || r.section_ref || r.location || "").toLowerCase();
    return ref.indexOf(sLow) !== -1 || sLow.indexOf(ref) !== -1;
  });
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // Lazy boot — pulled into _ensureBooted so a boot failure can no
  // longer short-circuit eli.register. Previously this block ran
  // synchronously at init() time; if the v2 module threw or wasn't
  // loaded yet, init() returned before reaching the eli.register call
  // below → tile click hit the "no launcher registered" path. Now the
  // tile is registered unconditionally, and we attempt the boot on the
  // first click instead. User sees an actual error if something's wrong.
  function _ensureBooted() {
    if (window._eliReviewRedlinesBooted) return true;
    if (typeof window._eliBootReviewRedlines !== "function") {
      eli.log.event("tool", "review_redlines_boot_missing", {});
      if (typeof showToast === "function") showToast("Review Redlines module didn't load — try Data Hub → Force re-install.", "err");
      return false;
    }
    try { window._eliBootReviewRedlines(); }
    catch (e) {
      eli.log.event("tool", "review_redlines_boot_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Review Redlines boot failed: " + (e && e.message || "unknown"), "err");
      return false;
    }
    try { if (typeof window._eliBootTeamCommentary === "function") window._eliBootTeamCommentary(); }
    catch (e) { eli.log.event("tool", "review_redlines_tc_boot_failed", { msg: e && e.message }); }
    return true;
  }

  // 2026-05-17: take a "before" snapshot the first time Review Redlines
  // opens this session, so a Version History → Compare later shows
  // exactly what the user accepted/rejected during this redline pass.
  // Logic refined per user request:
  //   • Tile open + NO past Review Redlines session in IDB → snapshot.
  //     This is a genuine fresh start; baseline didn't exist yet.
  //   • Tile open + past session EXISTS → skip. The baseline was
  //     captured back when that session originally started.
  //   • Start Fresh button (handled in _v2Module.js) → always snapshot.
  //     User explicitly chose to discard the past session and start
  //     over, so a fresh baseline is exactly what they want.
  // Per-session debounce on the tile path so re-entering the tool
  // doesn't redo the check.
  var _snapshotCheckedThisSession = false;
  // Check IDB for any persisted Review Redlines sessions. _v2Module.js
  // exposes openTrackPortSessionDb + TRACK_PORT_SESSION_STORE as window
  // globals so init.js can introspect across the bundle's file split.
  // Returns Promise<boolean>. Defaults to false (= "take snapshot") on
  // any error — better to over-capture than miss a baseline.
  function _hasPastSession() {
    return new Promise(function (resolve) {
      try {
        if (typeof window.openTrackPortSessionDb !== "function") { resolve(false); return; }
        window.openTrackPortSessionDb().then(function (db) {
          try {
            var storeName = window.TRACK_PORT_SESSION_STORE || "sessions";
            var tx = db.transaction(storeName, "readonly");
            var req = tx.objectStore(storeName).count();
            req.onsuccess = function () { resolve((req.result || 0) > 0); };
            req.onerror = function () { resolve(false); };
          } catch (_e) { resolve(false); }
        }).catch(function () { resolve(false); });
      } catch (_e) { resolve(false); }
    });
  }
  function _takeSnapshot(label) {
    try {
      if (eli && typeof eli.dispatch === "function") {
        var p = eli.dispatch("version_history", "snapshot", { label: label });
        // dispatch returns undefined when handler not registered (tool
        // not installed) — silent no-op, no error needed.
        if (p && typeof p.then === "function") {
          p.then(function (ok) {
            if (ok) eli.log.event("tool", "review_redlines_snapshot", { label: label });
          }).catch(function () { /* tolerate — snapshot is opportunistic */ });
        }
      }
    } catch (_e) { /* tolerate — version_history may not be loaded */ }
  }

  // ─── Tile handler ────────────────────────────────────────────────
  function _open() {
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    if (!_ensureBooted()) return;
    // 2026-05-18 v48: stat MOVED to tile-only wrapper below. _open is
    // also called by review_redlines:open / :run channels (compare's
    // post-diff dispatch), activity_restore handlers, and the
    // _restoreRedline fallback — counting every one inflated the
    // launch tally 3–5x in practice.
    // 2026-05-17: snapshot decision moved into _v2Module.js's runRedlineSummary.
    // It reads version_history, finds any "Review Redlines …" entries,
    // and either silently snapshots (first-ever) or surfaces the
    // 3-option start dialog (continue / new / restore). Keeping the
    // logic centralized there avoids double-snapshotting on every open.
    // Pull team guidance from GitHub on open — background, throttled to
    // once / 90s inside _tcPullRemote. This is what lets a teammate
    // RECEIVE published guidance without having to post a comment first.
    try {
      if (typeof window._tcPullRemote === "function") {
        window._tcPullRemote().catch(function () { /* tolerate — local guidance still works */ });
      }
    } catch (_tcPullErr) { /* tolerate */ }
    if (typeof window.runRedlineSummary !== "function") {
      if (typeof showToast === "function") showToast("Review Redlines failed to load — runRedlineSummary missing.", "err");
      return;
    }
    try { window.runRedlineSummary(); }
    catch (e) {
      eli.log.event("tool", "review_redlines_launch_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Review Redlines failed: " + (e.message || "unknown"), "err");
    }
  }

  // 2026-05-13 follow-up: rich activity restore. The scan-complete
  // activity entry (emitted by _v2Module.js after AI grouping finishes)
  // carries `{persistedSessionId, session}` as payload. The handler
  // re-opens the tool, then fetches the latest IDB-persisted session
  // (so AI-enriched fields like Net Impact land even if AI completed
  // after the activity row was written) and renders the workbench to
  // that snapshot. Falls back to the static payload's `session` when
  // IDB has no row (e.g., session storage was cleared). Without this
  // restore handler the entry was a dead link across kernel reloads.
  //
  // 2026-05-17 v11: do NOT call _open() during restore — _open()
  // invokes runRedlineSummary() which surfaces the "Review Redlines"
  // 3-option start dialog (Continue / New / Restore). For an explicit
  // restore from the activity feed, the user has already chosen — the
  // dialog is redundant and confusing. Replicate just the tool-ready
  // checks (API key, boot, stats) inline.
  function _ensureToolReadyForRestore() {
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return false;
    }
    if (!_ensureBooted()) return false;
    // 2026-05-18 v48: stat removed — restore is not a launch.
    return true;
  }
  function _restoreRedline(payload) {
    if (!_ensureToolReadyForRestore()) return;
    if (!payload) { _open(); return; }
    function _restoreWith(fresh) {
      try {
        if (window.TrackChangesPort && typeof window.TrackChangesPort.setSession === "function") {
          window.TrackChangesPort.setSession(fresh);
        }
        if (typeof window.renderTrackPortWorkbench === "function") {
          window.renderTrackPortWorkbench(fresh);
        }
      } catch (e) {
        eli.log.event("tool", "review_redlines_restore_failed", { msg: e && e.message });
      }
    }
    var id = payload.persistedSessionId
      || (payload.session && payload.session.persistedSessionId);
    var fallback = payload.session || payload;
    if (id && typeof window.openTrackPortSessionDb === "function") {
      window.openTrackPortSessionDb().then(function (db) {
        return new Promise(function (resolve) {
          try {
            var tx = db.transaction(window.TRACK_PORT_SESSION_STORE, "readonly");
            var req = tx.objectStore(window.TRACK_PORT_SESSION_STORE).get(id);
            req.onsuccess = function () { resolve(req.result); };
            req.onerror = function () { resolve(null); };
          } catch (e) { resolve(null); }
        }).finally(function () { try { db.close(); } catch (_) {} });
      }).then(function (row) {
        var fresh = (row && row.session) ? row.session : fallback;
        _restoreWith(fresh);
      }).catch(function () { _restoreWith(fallback); });
    } else {
      _restoreWith(fallback);
    }
  }
  // 2026-05-17: expose the snapshot helper to _v2Module.js (separate
  // bundle file, IIFE-isolated) so its "Start Fresh" button can take a
  // fresh baseline snapshot. Window global is the bundler-safe
  // cross-file communication path (the bundler eval's each top-level
  // function in its own scope). _v2Module.js reads this via
  // typeof window._eli3_rr_takeSnapshot === "function".
  try {
    window._eli3_rr_takeSnapshot = function (label) {
      _takeSnapshot(label || "Start Fresh — Review Redlines");
    };
  } catch (_e) { /* tolerate — non-browser context */ }

  eli.register({
    tile: { app_review_redlines: function () {
      // 2026-05-18 v49: stack-trace instrumentation — user reports
      // review_redlines is logged on every ELI load. Persist trace +
      // event-source so we can see what's calling it (real click vs
      // programmatic). Mirror of the legal_risks tile instrumentation.
      try {
        var lastEvtType = (window.event && window.event.type) || null;
        var lastEvtTarget = null;
        try {
          if (window.event && window.event.target) {
            lastEvtTarget = (window.event.target.id || "") + "/" +
              (window.event.target.className || "").toString().slice(0, 80);
          }
        } catch (_ignore) {}
        var stack = "";
        try { throw new Error("review_redlines_tile_trace"); }
        catch (te) { stack = (te.stack || "").split("\n").slice(0, 10).join(" | "); }
        var diag = {
          at: new Date().toISOString(),
          evtType: lastEvtType,
          evtTarget: lastEvtTarget,
          stack: stack.slice(0, 1200),
        };
        eli.log.event("review_redlines_tile_fired", diag);
        try {
          if (eli.storage && typeof eli.storage.put === "function") {
            eli.storage.put("config", {
              key: "_review_redlines_tile_trace_" + Date.now(),
              diag: diag,
            }).catch(function () {});
          }
        } catch (_persistErr) {}
      } catch (_traceErr) {}
      try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedReviewRedlines"); } catch (e) {}
      _open();
    } },
    // Programmatic launch for cross-tool callers (compare's runVersionCompare
    // dispatches into Review Redlines after a deep-diff finishes). NO stat
    // record — these are not user-initiated launches.
    review_redlines: { open: _open, run: _open },
    // Activity restore — v2 activity entries use "review-redline" /
    // "trackport". Match both. "review-redline" is the rich-payload one
    // emitted by the scan-complete add (carries persistedSessionId);
    // the others are tolerance for older payloads.
    activity_restore: {
      "review-redline":   _restoreRedline,
      "review_redlines":  function () { _open(); },
      "trackport":        function () { _open(); },
    },
  });

  // 2026-05-13 item 9: removed the open-time activity entry — it was
  // payloadless ("Opened Track-Port workbench" with `{ts:Date.now()}`)
  // and restoring it just re-opened the empty workbench, NOT the
  // session state. The meaningful entry is added on SCAN COMPLETE
  // (_v2Module.js, after AI grouping finishes) — that one has the full
  // session payload + restoreFn that calls TrackChangesPort.setSession
  // + renderTrackPortWorkbench, properly restoring the AI-enriched
  // results. One entry per scan, restorable to its actual state.

  // ─── Boot-time team-commentary pull ──────────────────────────────
  // Fire the GitHub pull shortly after init so any new team commentary
  // surfaces via toast the moment the kernel is ready — without forcing
  // the user to open Review Redlines first. _eliBootTeamCommentary only
  // defines the window._tc* surface (no Word.run / heavy work), so
  // booting it at init is cheap. The pull itself is async + tolerant
  // of missing PAT / cipher (silent no-op when creds aren't set).
  // Deferred 1.5s so the kernel finishes manifest sync + dashboard
  // paint before we hit the network — keeps the boot-to-interactive
  // budget (≤600ms per CLAUDE.md) intact.
  try {
    if (typeof window._eliBootTeamCommentary === "function") {
      window._eliBootTeamCommentary();
    }
  } catch (e) {
    eli.log.event("tool", "review_redlines_tc_boot_failed", { msg: e && e.message });
  }
  setTimeout(function () {
    try {
      if (typeof window._tcPullRemote === "function") {
        window._tcPullRemote().catch(function () { /* tolerate */ });
      }
    } catch (_) { /* tolerate */ }
  }, 1500);

  eli.log.event("tool", "review_redlines_initialized", {});
}

jsonTools.css:
/* tools/review_redlines/style.css
 * Track-Port (Review Redlines) panel styles.
 * The v2 module renders with inline styles for almost everything; this
 * file only provides the handful of class-based hooks that v2 also used
 * via taskpane.css. Most rules are scoped to `#tpFocusShell`.
 */

/* Status badge in the focus-shell header — flips through "ready" /
 * "scanning" / "waiting on AI" states; kept as a class so the v2 code's
 * `setTrackPortStatus(msg)` (which writes to a DOM element by id) can
 * style it consistently. */
.tpStatusReady    { color: #2e7d32; }
.tpStatusScanning { color: #1565c0; }
.tpStatusError    { color: #c62828; }

/* Section dropdown chevron flips when the section is expanded. */
.tpSectionChevron { transition: transform 0.18s; display: inline-block; }
.tpSectionChevron._open { transform: rotate(90deg); }

/* Per-row buttons (Accept / Reject / Fallback / Locate) — neutral
 * platinum pills, color flips when locked-in. */
.tpPbSwitchBtn,
.tpSetAttEmail,
.tpSetPbDelete,
.tpSetPbEdit {
  font: 700 11px/1 'Inter', sans-serif;
  padding: 6px 10px;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #455a64;
  border: 1px solid #b0bec5;
  cursor: pointer;
  transition: all 0.12s;
}
.tpPbSwitchBtn:hover,
.tpSetAttEmail:hover,
.tpSetPbEdit:hover { background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%); color: #1565c0; border-color: #90caf9; }
.tpSetPbDelete:hover { background: #fef2f2; color: #b91c1c; border-color: #fca5a5; }

/* ─── Progress card ──────────────────────────────────────────────────
 * Centered overlay shown during AI scan + audit. review_redlines unique:
 * the workbench paints before the audit completes, so users need a
 * visible "still working" signal. Card auto-dismisses on completion. */
.rr-progress-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999999;
  animation: rrProgressFadeIn 0.18s ease-out;
}
@keyframes rrProgressFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
.rr-progress-card {
  width: 440px;
  max-width: 92%;
  background: linear-gradient(180deg, #1e293b 0%, #0f172a 100%);
  border: 1px solid #c9a227;
  padding: 28px 32px 24px;
  color: #f1f5f9;
  text-align: center;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45);
}
.rr-progress-card.rr-progress-done {
  box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.45), 0 14px 40px rgba(0, 0, 0, 0.45);
  transition: box-shadow 0.3s;
}
.rr-progress-title {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #c9a227;
}
.rr-progress-sub {
  font-size: 12px;
  font-weight: 500;
  color: #cbd5e1;
  margin-top: 4px;
  margin-bottom: 18px;
}
.rr-progress-rail {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  margin: 14px 0 6px;
}
.rr-progress-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 0 0 auto;
  width: 72px;
}
.rr-progress-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #334155;
  border: 1px solid #475569;
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s;
  margin-top: 2px;
}
.rr-progress-step.active .rr-progress-dot {
  background: #c9a227;
  border-color: #c9a227;
  animation: rrProgressPulse 1.2s ease-in-out infinite;
}
.rr-progress-step.done .rr-progress-dot {
  background: #c9a227;
  border-color: #c9a227;
}
.rr-progress-label {
  font-size: 9.5px;
  font-weight: 700;
  color: #64748b;
  margin-top: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-align: center;
  line-height: 1.2;
}
.rr-progress-step.active .rr-progress-label,
.rr-progress-step.done .rr-progress-label {
  color: #f1f5f9;
}
.rr-progress-line {
  height: 1px;
  width: 28px;
  background: #334155;
  margin: 7px 0 0;
  align-self: flex-start;
}
.rr-progress-status {
  font-size: 16px;
  font-weight: 600;
  color: #f1f5f9;
  margin-top: 18px;
  margin-bottom: 4px;
}
.rr-progress-subcount {
  font-size: 12px;
  color: #94a3b8;
  min-height: 16px;
}
.rr-progress-elapsed {
  font-size: 11px;
  color: #64748b;
  margin-top: 14px;
  font-family: ui-monospace, 'SF Mono', Menlo, monospace;
  letter-spacing: 0.3px;
}
.rr-progress-cancel {
  margin-top: 18px;
  background: linear-gradient(180deg, #f8fafc 0%, #cbd5e1 100%);
  border: 1px solid #94a3b8;
  color: #1e293b;
  font: 700 11px/1 'Inter', sans-serif;
  padding: 9px 26px;
  cursor: pointer;
  border-radius: 0;
  transition: all 0.12s;
  text-transform: uppercase;
  letter-spacing: 0.6px;
}
.rr-progress-cancel:hover:not(:disabled) {
  background: linear-gradient(180deg, #fff 0%, #e2e8f0 100%);
}
.rr-progress-cancel:disabled {
  opacity: 0.55;
  cursor: default;
}
@keyframes rrProgressPulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.30); }
  50%      { box-shadow: 0 0 0 7px rgba(201, 162, 39, 0.55); }
}

/* 2026-05-17: premium scrollbar for the combined GUIDANCE pane body.
 * Cream track + gold gradient thumb so the scroll affordance reads as
 * part of the pane's gold/cream design, not a default browser bar.
 * Applied to .rr-guidance-body — the inner div of the GUIDANCE
 * <details> pane. max-height caps at half-viewport so long clause /
 * fallback guidance scrolls inside the pane instead of pushing the
 * focus shell layout down. */
.rr-guidance-body {
  /* JS sets --rr-guidance-max dynamically on guidance-open / workspace-
     toggle / window-resize so the pane fills the empty vertical space
     between its top and the workspace. Falls back to 50vh when JS
     hasn't run yet (first paint, JS error, headless). */
  max-height: var(--rr-guidance-max, 50vh);
  overflow-y: auto;
  overflow-x: hidden;
  /* Firefox */
  scrollbar-width: thin;
  scrollbar-color: #d4af37 #fef9e7;
}
/* WebKit (Chrome / Edge / Safari) — premium gold treatment. */
.rr-guidance-body::-webkit-scrollbar {
  width: 8px;
}
.rr-guidance-body::-webkit-scrollbar-track {
  background: #fef9e7;
  border-left: 1px solid rgba(201, 162, 39, 0.18);
}
.rr-guidance-body::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #f3e1a1 0%, #d4af37 50%, #a8841d 100%);
  border-radius: 4px;
  border: 1px solid rgba(168, 132, 29, 0.4);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35);
}
.rr-guidance-body::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, #f6e7b0 0%, #e2c352 50%, #b8902c 100%);
}
.rr-guidance-body::-webkit-scrollbar-thumb:active {
  background: linear-gradient(180deg, #e0c970 0%, #b8902c 50%, #8a6818 100%);
}
